diff --git a/web/src/lib/evaluation-api.ts b/web/src/lib/evaluation-api.ts
index 5d69b02..1da7a4a 100644
--- a/web/src/lib/evaluation-api.ts
+++ b/web/src/lib/evaluation-api.ts
@@ -182,8 +182,53 @@ export const evaluationApi = {
     get<ProductionTraceView>(
       `/production/traces/${encodeURIComponent(id)}/trace${caseId ? `?case_id=${encodeURIComponent(caseId)}` : ""}`,
     ),
+  // §61 Online Eval
+  evalPolicies: () => get<EvalPolicyRow[]>("/eval-policies"),
+  evaluateProductionTrace: (id: string, policy: string) =>
+    post<EvaluationResult>(
+      `/production/traces/${encodeURIComponent(id)}/evaluate`,
+      { policy },
+    ),
+  productionEvaluations: (id: string) =>
+    get<EvaluationResult[]>(`/production/traces/${encodeURIComponent(id)}/evaluations`),
 };

+export interface EvalPolicyRow {
+  id: string;
+  display_name: string;
+  description: string;
+  judge_model: string | null;
+  timeout_seconds: number;
+  metrics: { id: string; threshold: number | null }[];
+}
+
+export interface EvaluationRow {
+  case_id: string;
+  metric: string;
+  threshold: number | null;
+  score: number | null;
+  verdict: "pass" | "fail" | "error" | "skipped";
+  reason: string | null;
+}
+
+export interface EvaluationSummary {
+  policy: string;
+  cases_total: number;
+  cases_evaluated: number;
+  cases_unextractable: string[];
+  metrics: Record<
+    string,
+    { pass: number; fail: number; error: number; mean_score: number | null }
+  >;
+}
+
+export interface EvaluationResult {
+  evaluation_id: string;
+  trace_id?: string;
+  summary: EvaluationSummary;
+  rows: EvaluationRow[];
+}
+
 export interface ProductionTraceMeta {
   trace_id: string;
   source: string;

diff --git a/web/src/pages/Production.tsx b/web/src/pages/Production.tsx
index 214cd79..99bca0c 100644
--- a/web/src/pages/Production.tsx
+++ b/web/src/pages/Production.tsx
@@ -1,7 +1,7 @@
 import * as React from "react";
-import { useQuery } from "@tanstack/react-query";
+import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
 import { Link, useParams } from "react-router";
-import { ArrowLeft, Radio } from "lucide-react";
+import { ArrowLeft, Play, Radio } from "lucide-react";

 import { Mono, PageHeader, Section } from "@/components/common/primitives";
 import { QueryState } from "@/components/common/states";
@@ -15,9 +15,25 @@ import {
   SelectTrigger,
   SelectValue,
 } from "@/components/ui/select";
+import {
+  Table,
+  TableBody,
+  TableCell,
+  TableHead,
+  TableHeader,
